410	/** Read a response body as text, aborting once MAX_BYTES is exceeded. */
411	async function readCapped(res: Response): Promise<{ text: string; bytes: number; truncated: boolean }> {
412	  const body = res.body;
413	  if (!body) {
414	    const text = await res.text();
415	    const bytes = Buffer.byteLength(text);
416	    return { text: text.slice(0, MAX_BYTES), bytes, truncated: bytes > MAX_BYTES };
417	  }
418	  const reader = body.getReader();
419	  const chunks: Uint8Array[] = [];
420	  let total = 0;
421	  let truncated = false;
422	  for (;;) {
423	    const { done, value } = await reader.read();
424	    if (done) break;
425	    if (value) {
426	      total += value.byteLength;
427	      if (total > MAX_BYTES) {
428	        const keep = value.byteLength - (total - MAX_BYTES);
429	        if (keep > 0) chunks.push(value.subarray(0, keep));
430	        truncated = true;
431	        await reader.cancel().catch(() => {});
432	        break;
433	      }
434	      chunks.push(value);
435	    }
436	  }
437	  const buf = Buffer.concat(chunks.map((c) => Buffer.from(c)));
438	  return { text: buf.toString("utf8"), bytes: Math.min(total, MAX_BYTES), truncated };
439	}
440	
441	/**
442	 * Fetch a single operator-supplied URL safely and extract brand signals. Never
443	 * throws — returns { ok:false, error } on any refusal or failure. Follows at most
444	 * MAX_REDIRECTS redirects, re-validating each hop's host.
445	 */
446	export async function scrapeSite(rawUrl: string): Promise<ScrapeResult> {
447	  const base: ScrapeResult = {
448	    ok: false,
449	    url: String(rawUrl ?? "").trim(),
450	    finalUrl: "",
451	    status: 0,
452	    bytes: 0,
453	    extraction: emptyExtraction(),
454	    error: "",
455	  };
456	
457	  let current: URL;
458	  try {
459	    current = parseHttpUrl(rawUrl);
460	  } catch (err) {
461	    return { ...base, error: (err as Error).message };
462	  }
463	
464	  const controller = new AbortController();
465	  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
466	  try {
467	    for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
468	      try {
469	        await assertHostPublic(current.hostname);
470	      } catch (err) {
471	        return { ...base, finalUrl: current.toString(), error: (err as Error).message };
472	      }
473	
474	      let res: Response;
475	      try {
476	        res = await fetch(current.toString(), {
477	          method: "GET",
478	          redirect: "manual",
479	          signal: controller.signal,
480	          headers: {
481	            "user-agent": USER_AGENT,
482	            accept: "text/html,application/xhtml+xml",
483	            "accept-language": "en",
484	          },
485	        });
486	      } catch (err) {
487	        const msg = controller.signal.aborted ? `Timed out after ${TIMEOUT_MS}ms.` : String((err as Error).message);
488	        return { ...base, finalUrl: current.toString(), error: `Fetch failed: ${msg}` };
489	      }
490	
491	      // Redirect? Re-parse + re-validate the next hop.
492	      if (res.status >= 300 && res.status < 400) {
493	        const loc = res.headers.get("location");
494	        if (!loc) return { ...base, finalUrl: current.toString(), status: res.status, error: "Redirect without a Location." };
495	        if (hop === MAX_REDIRECTS) {
496	          return { ...base, finalUrl: current.toString(), status: res.status, error: `Too many redirects (>${MAX_REDIRECTS}).` };
497	        }
498	        let next: URL;
499	        try {
500	          next = parseHttpUrl(new URL(loc, current).toString());
501	        } catch (err) {
502	          return { ...base, finalUrl: current.toString(), status: res.status, error: `Refused redirect: ${(err as Error).message}` };
503	        }
504	        current = next;
505	        continue;
506	      }
507	
508	      if (!res.ok) {
509	        return { ...base, finalUrl: current.toString(), status: res.status, error: `HTTP ${res.status}.` };
510	      }
511	
512	      const ctype = res.headers.get("content-type") ?? "";
