19	/** Upload an attachment to a card. Admin only. Stored on disk so it can be read
20	 *  and acted on directly. `?cardId=` in the query. */
21	export async function POST(req: NextRequest) {
22	  try {
23	    await requireAdmin();
24	  } catch {
25	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
26	  }
27	  const cardId = req.nextUrl.searchParams.get("cardId") ?? "";
28	  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true } });
29	  if (!card) return NextResponse.json({ error: "Card not found" }, { status: 404 });
30	
31	  const form = await req.formData();
32	  const file = form.get("file");
33	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
34	
35	  const mime = file.type || "application/octet-stream";
36	  const kind = kindFor(mime);
37	  const cap = kind === "VIDEO" ? MAX_VIDEO : MAX_OTHER;
38	  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });
39	
40	  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
