45	    await fs.writeFile(join(dir, storedName), Buffer.from(await file.arrayBuffer()));
46	  } catch (e) {
47	    // Almost always a permissions problem on BOARD_UPLOAD_DIR (the web process
48	    // couldn't create/write it — /opt/nxeon is root-owned, the app runs as nxeon).
49	    // Surface it instead of throwing an opaque 500 the client would swallow — that
50	    // was exactly the "upload does nothing, no preview" bug.
51	    console.error("[board] attachment write failed:", e);
