12	  try {
13	    await requireAdmin();
14	  } catch {
15	    return new NextResponse("Forbidden", { status: 403 });
16	  }
17	  const { id } = await params;
18	  const att = await db.cardAttachment.findUnique({ where: { id } });
19	  if (!att) return new NextResponse("Not found", { status: 404 });
20	  const path = join(BOARD_UPLOAD_DIR, "board", att.cardId, att.storedName);
21	  let size: number;
22	  try {
23	    size = (await fs.stat(path)).size;
24	  } catch {
25	    return new NextResponse("Missing", { status: 404 });
26	  }
27	
28	  const range = req.headers.get("range");
29	  const disposition = att.kind === "FILE" ? `attachment; filename="${att.filename.replace(/"/g, "")}"` : "inline";
30	  const baseHeaders: Record<string, string> = { "Content-Type": att.mime, "Content-Disposition": disposition, "Accept-Ranges": "bytes" };
31	
32	  if (range) {
33	    const m = /bytes=(\d+)-(\d*)/.exec(range);
34	    if (m) {
35	      const start = Number(m[1]);
36	      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
37	      if (start <= end && start < size) {
38	        const stream = createReadStream(path, { start, end });
39	        return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
40	          status: 206,
41	          headers: { ...baseHeaders, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) },
42	        });
43	      }
44	    }
45	  }
46	  const stream = createReadStream(path);
47	  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
48	    status: 200,
49	    headers: { ...baseHeaders, "Content-Length": String(size) },
50	  });
51	}
