50	/** True if an IPv6 address sits in a range we refuse to connect to. */
51	function isBlockedIpv6(ip: string): boolean {
52	  let addr = ip.toLowerCase();
53	  // Strip a zone id (fe80::1%eth0) before classifying.
54	  const pct = addr.indexOf("%");
55	  if (pct !== -1) addr = addr.slice(0, pct);
56	
57	  // IPv4-mapped / -compatible (::ffff:1.2.3.4) — classify by the embedded IPv4.
58	  const mapped = addr.match(/:((?:\d{1,3}\.){3}\d{1,3})$/);
59	  if (mapped) return isBlockedIpv4(mapped[1]);
60	
61	  if (addr === "::1" || addr === "::") return true; // loopback / unspecified
62	  const head = addr.split(":")[0] ?? "";
63	  const h = parseInt(head || "0", 16);
64	  if (Number.isNaN(h)) return true; // unparseable — refuse
65	  // fc00::/7 unique-local (fc.. or fd..)
66	  if ((h & 0xfe00) === 0xfc00) return true;
67	  // fe80::/10 link-local
68	  if ((h & 0xffc0) === 0xfe80) return true;
69	  return false;
70	}
