2	import { Resolver } from "node:dns/promises";
3	import { jsonError, readField } from "@/lib/tools/api";
4	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
5	import { extractHost, isPlausibleHost } from "@/lib/tools/net-guard";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
12	 * node:dns. Public DNS only (no connections are made to the target), but we still
13	 * validate the hostname and cap output. Rate-limited per IP.
14	 */
15	
16	const TIMEOUT_MS = 5000;
17	const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
18	type RecordType = (typeof TYPES)[number];
19	
20	function withTimeout<T>(p: Promise<T>): Promise<T> {
21	  return Promise.race([
22	    p,
23	    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
24	  ]);
25	}
26	
27	export async function POST(req: Request) {
28	  const limited = toolRateLimitByIp(req, "dns", { max: 30, windowMs: 60_000 });
29	  if (limited) return limited;
30	
31	  const raw = await readField(req, "domain");
32	  const host = extractHost(raw);
33	  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
34	  if (host === "localhost") return jsonError("That host is not allowed.");
35	
36	  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });
37	
38	  async function resolveType(type: RecordType): Promise<string[]> {
39	    try {
40	      switch (type) {
41	        case "A":
42	          return await withTimeout(resolver.resolve4(host!));
43	        case "AAAA":
44	          return await withTimeout(resolver.resolve6(host!));
45	        case "MX": {
46	          const mx = await withTimeout(resolver.resolveMx(host!));
47	          return mx
48	            .sort((a, b) => a.priority - b.priority)
49	            .map((r) => `${r.priority}\t${r.exchange}`);
50	        }
51	        case "TXT": {
52	          const txt = await withTimeout(resolver.resolveTxt(host!));
53	          return txt.map((chunks) => chunks.join(""));
54	        }
55	        case "NS":
56	          return await withTimeout(resolver.resolveNs(host!));
57	        case "CNAME":
58	          return await withTimeout(resolver.resolveCname(host!));
59	        case "SOA": {
60	          const soa = await withTimeout(resolver.resolveSoa(host!));
61	          return [
62	            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
63	          ];
64	        }
65	      }
66	    } catch {
67	      return [];
68	    }
69	  }
70	
71	  try {
72	    const settled = await Promise.all(
73	      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
74	    );
75	    const records: Record<string, string[]> = {};
76	    for (const [t, vals] of settled) records[t] = vals;
77	    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
78	    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
79	    return NextResponse.json({ ok: true, host, records });
80	  } catch {
81	    return jsonError("DNS lookup failed.", 502);
82	  }
83	}
