// ---------------------------------------------------------------------------
// Pinned dispatcher — close the DNS-rebinding TOCTOU window.
// ---------------------------------------------------------------------------

/**
 * An undici Agent whose DNS resolution is hard-wired to an already-vetted
 * address. The URL still supplies the Host header + TLS SNI, so virtual hosts
 * and certificate validation behave normally — only the address we dial is
 * fixed, to the exact IP `assertHostPublic` just approved. Without this, undici
 * re-resolves the hostname on connect and a 0-TTL record that answered public on
 * the check can answer 127.0.0.1 / 169.254.169.254 / 10.x on the connect.
 *
 * undici's connector calls `lookup` with `{ all: true }` and expects an ARRAY of
 * `{ address, family }`; node's `net.connect` contract is the positional
 * `(err, address, family)` form. Both shapes are answered here (mirrors the
 * http-headers tool) — getting it wrong fails every request at runtime, not at
 * build time.
 */
type LookupCallback = (err: Error | null, addresses: unknown, family?: number) => void;

function pinnedAgent(address: string): Agent {
  const family = isIP(address);
  return new Agent({
    connect: {
      lookup: (_hostname: string, options: { all?: boolean }, callback: LookupCallback) => {
        if (options?.all) callback(null, [{ address, family }]);
        else callback(null, address, family);
      },
    } as never,
  });
}

